INSERT INTO homepage_sections (tenant_id, section_type, title, subtitle, content, settings, sort_order, is_visible) VALUES ('0c247ff0-b39a-53fd-b6ee-edace276cbf6', 'hero', 'Wijnen met een verhaal', 'Rechtstreeks van kleine domeinen in Frankrijk, Italië en Spanje', '{"image_url": "", "button_text": "Ontdek de wijnen", "button_link": "/producten", "text_alignment": "left", "overlay_opacity": 0.4}'::jsonb, '{}'::jsonb, 0, true);
