INSERT INTO homepage_sections (tenant_id, section_type, title, subtitle, content, settings, sort_order, is_visible) VALUES ('0c247ff0-b39a-53fd-b6ee-edace276cbf6', 'text_image', 'Van het domein naar je tafel', null, '{"text": "Elke wijn proeven we zelf op het domein. We kiezen kleine wijnboeren die met respect voor de natuur werken, en vertellen je eerlijk bij welk gerecht hij past.", "image_url": "", "image_position": "right", "button_text": "Bekijk alles", "button_link": "/producten"}'::jsonb, '{}'::jsonb, 3, true);
INSERT INTO homepage_sections (tenant_id, section_type, title, subtitle, content, settings, sort_order, is_visible) VALUES ('0c247ff0-b39a-53fd-b6ee-edace276cbf6', 'faq', 'Goed om te weten', null, '{"items": [{"question": "Moet ik 18 zijn?", "answer": "Ja, alcohol verkopen we enkel aan meerderjarigen. Bij de levering kan naar je identiteitskaart gevraagd worden."}, {"question": "Leveren jullie per doos?", "answer": "Je mag flessen mixen. De verzending is gratis vanaf €150."}, {"question": "Is dit een echte winkel?", "answer": "Nee, dit is een demowinkel van SellQo. Je kan alles uitproberen, ook afrekenen, maar er wordt niets verzonden of aangerekend."}]}'::jsonb, '{}'::jsonb, 4, true);